css:
.d-sub{width:100%;max-width:340px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.d-sub-frame{position:relative;height:120px;background:linear-gradient(160deg,color-mix(in srgb,var(--ink) 78%,var(--paper)),color-mix(in srgb,var(--ink) 50%,var(--paper)))}
.d-sub-line{position:absolute;left:12px;right:12px;bottom:12px;margin:0;padding:4px 8px;background:color-mix(in srgb,var(--ink) 78%,transparent);color:var(--paper);font-size:11px;line-height:1.6;border-radius:2px;transition:opacity 160ms var(--ease)}
.d-sub-line.off{opacity:0}
.d-sub-bar{display:flex;gap:6px;padding:8px 12px}
.d-sub-bar button{padding:3px 10px;border:1px solid var(--line);border-radius:999px;background:var(--bg);color:var(--ink);font:inherit;font-size:11px;cursor:pointer}
.d-sub-bar button[aria-pressed="false"]{color:var(--faint)}

init:
root => {
  var line = root.querySelector('[data-line]');
  var toggle = root.querySelector('[data-toggle]');
  var size = root.querySelector('[data-size]');
  if (!line || !toggle) return;
  var on = true, sizes = [9, 11, 13], si = 1;
  toggle.addEventListener('click', function () {
    on = !on;
    toggle.setAttribute('aria-pressed', on ? 'true' : 'false');
    toggle.textContent = on ? '字幕 开' : '字幕 关';
    line.classList.toggle('off', !on);
  });
  if (size) size.addEventListener('click', function () { si = (si + 1) % 3; line.style.fontSize = sizes[si] + 'px'; size.textContent = '字号 ' + ['小', '中', '大'][si]; });
}
